export interface RouteStair {
  id: string;
  name: string;
  neighborhood: string;
  lat: number | null;
  lng: number | null;
  steps: string;
  needsVerification: boolean;
}
export type Point = [number, number];
export interface Network {
  version: number;
  updatedAt: string;
  nodes: Point[];
  edges: [number, number, number][];
  snaps: Record<string, [number, number]>;
}
